#[test]
fn rust_block_matches_the_oracle_outputs() {
    let mut worst = 0.0f32;
    for (mode, words, st, input, out) in CASES {
        let mut stage = FwLp24::new(mode, 64.0, 0.0);
        stage.load(words.map(|p| p.map(f)), st.map(|s| s.map(f)));
        let got = stage.block(input.map(|fr| fr.map(f)));
        for i in 0..4 {
            for ch in 0..2 {
                worst = worst.max((got[i][ch] - f(out[i][ch])).abs());
            }
        }
    }
    assert!(worst < 2e-5, "worst deviation {worst}");
}
